/**
 * Bulk-safe logic for ContactTrigger.
 *
 * Budget per insert/update of up to 200 contacts (before + after together):
 *   - 1 SOQL query (accounts are loaded once and cached for the insert's
 *     before and after phases)
 *   - 1 DML statement (a single update of accounts that need a phone)
 *
 * Runs as inherited sharing, which, when invoked from a trigger, executes in
 * system context, matching the behaviour of the original trigger.
 */
public inherited sharing class ContactTriggerHandler {

    // Accounts loaded for the current DML operation. Populated in the before
    // phase and reused in the after insert phase, then cleared.
    private static Map<Id, Account> accountCache = new Map<Id, Account>();

    /**
     * Before insert / before update: default MailingCountry from the account's
     * BillingCountry, and on insert default LeadSource from the account's
     * AccountSource. Only fills blank fields.
     */
    public static void beforeUpsert(List<Contact> contacts, Boolean isInsert) {
        accountCache.clear();

        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        loadAccounts(accountIds);

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountCache.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert: if an account has no phone, the first contact (in trigger
     * order) of that account with a phone sets the account phone. Later
     * contacts see the in-memory value already set and are skipped.
     */
    public static void afterInsert(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (!accountIds.isEmpty()) {
            // Normally fully served from the cache populated in beforeUpsert.
            loadAccounts(accountIds);

            Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
            for (Contact c : contacts) {
                if (c.AccountId == null || String.isBlank(c.Phone)) {
                    continue;
                }
                Account a = accountCache.get(c.AccountId);
                if (a == null || String.isNotBlank(a.Phone)) {
                    continue;
                }
                a.Phone = c.Phone;
                accountsToUpdate.put(a.Id, a);
            }

            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate.values();
            }
        }

        accountCache.clear();
    }

    /**
     * Queries only the accounts not already cached, in a single SOQL query.
     */
    private static void loadAccounts(Set<Id> accountIds) {
        Set<Id> missing = new Set<Id>();
        for (Id accountId : accountIds) {
            if (!accountCache.containsKey(accountId)) {
                missing.add(accountId);
            }
        }
        if (missing.isEmpty()) {
            return;
        }
        for (Account a : [
            SELECT Id, BillingCountry, AccountSource, Phone
            FROM Account
            WHERE Id IN :missing
        ]) {
            accountCache.put(a.Id, a);
        }
    }
}
