public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT_PATH = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CURRENCY_CODE_PATTERN = Pattern.compile('[A-Z]{3}');

    /**
     * Retrieves exchange rates from the FB_Exchange_Rates Named Credential.
     *
     * @param baseCurrency   ISO-style three letter base currency code.
     * @param quoteCurrencies Set of three letter quote currency codes.
     * @return Map keyed by normalised quote code to its rate relative to the base.
     * @throws ExchangeRateException on invalid input, HTTP failure, or unusable response.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String base = normaliseCode(baseCurrency);

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency code is required.');
        }

        Set<String> quotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            quotes.add(normaliseCode(quote));
        }

        List<String> quoteList = new List<String>(quotes);
        quoteList.sort();

        String endpoint = ENDPOINT_PATH
            + '?base=' + base
            + '&symbols=' + String.join(quoteList, ',');

        HttpResponse response = sendWithRetry(endpoint);

        Integer statusCode = response.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status ' + statusCode + '.'
            );
        }

        return parseRates(response.getBody(), quotes);
    }

    /* ----------------------------------------------------------------------
     * Helpers
     * ---------------------------------------------------------------------- */

    private static String normaliseCode(String rawCode) {
        if (rawCode == null) {
            throw new ExchangeRateException('Currency code must not be null.');
        }
        String code = rawCode.trim().toUpperCase();
        if (!CURRENCY_CODE_PATTERN.matcher(code).matches()) {
            throw new ExchangeRateException(
                'Invalid currency code: "' + rawCode + '". Expected exactly three letters A-Z.'
            );
        }
        return code;
    }

    private static HttpRequest buildRequest(String endpoint) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        return request;
    }

    /**
     * Sends the request; on HTTP 503 retries exactly once with an identical request.
     */
    private static HttpResponse sendWithRetry(String endpoint) {
        Http http = new Http();
        HttpResponse response = http.send(buildRequest(endpoint));

        if (response.getStatusCode() == 503) {
            response = http.send(buildRequest(endpoint));
        }

        return response;
    }

    private static Map<String, Decimal> parseRates(String body, Set<String> requestedCodes) {
        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Unable to parse exchange rate response: root is not a JSON object.');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;
        Object ratesObject = root.get('rates');

        if (!(ratesObject instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Unable to parse exchange rate response: "rates" object is missing.');
        }

        Map<String, Object> rates = (Map<String, Object>) ratesObject;
        Map<String, Decimal> result = new Map<String, Decimal>();

        for (String code : requestedCodes) {
            if (!rates.containsKey(code)) {
                throw new ExchangeRateException('No exchange rate returned for currency: ' + code + '.');
            }

            Object rawRate = rates.get(code);
            if (rawRate == null) {
                throw new ExchangeRateException('No exchange rate returned for currency: ' + code + '.');
            }

            Decimal rate;
            try {
                rate = Decimal.valueOf(String.valueOf(rawRate));
            } catch (Exception e) {
                throw new ExchangeRateException(
                    'Unable to parse exchange rate for currency ' + code + '.'
                );
            }

            result.put(code, rate);
        }

        return result;
    }
}
