/**
 * Groups the contacts of a set of accounts by the lower-cased domain part of their email address.
 *
 * - Runs in the caller's sharing context (with sharing).
 * - Uses a single SOQL query for the whole set, so it is bulk-safe.
 * - Contacts without an email are excluded.
 * - A null or empty input set returns an empty map.
 */
public with sharing class ContactDomainService {

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        for (Contact c : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
        ]) {
            String domain = extractDomain(c.Email);
            if (String.isBlank(domain)) {
                continue;
            }

            if (!contactsByDomain.containsKey(domain)) {
                contactsByDomain.put(domain, new List<Contact>());
            }
            contactsByDomain.get(domain).add(c);
        }

        return contactsByDomain;
    }

    /**
     * Returns the lower-cased domain part of an email address, or null if none can be determined.
     */
    @TestVisible
    private static String extractDomain(String email) {
        if (String.isBlank(email)) {
            return null;
        }

        String trimmed = email.trim();
        Integer atIndex = trimmed.lastIndexOf('@');
        if (atIndex < 0 || atIndex == trimmed.length() - 1) {
            return null;
        }

        return trimmed.substring(atIndex + 1).toLowerCase();
    }
}
