/**
 * Backs the admin "record finder" Lightning component.
 *
 * Builds a single SOQL query from user-supplied object/field names and equality filters.
 *
 * Security model:
 *  - "with sharing" so the running user's record sharing applies.
 *  - Object, field, filter and order-by names are resolved against the Schema describe
 *    (case-insensitively) and replaced with their canonical API names. Only names that
 *    exist, are readable by the running user, and have the required capability
 *    (filterable / sortable) are ever placed into the SOQL text.
 *  - Filter values are never concatenated. They are passed as named bind variables.
 *  - Database.queryWithBinds(..., AccessLevel.USER_MODE) enforces object and field-level
 *    security at query time as a second layer of defence.
 *
 * Every validation failure, and any query failure, is reported as SearchException.
 */
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    /**
     * Runs an equality-filtered query against any queryable object the running user can read.
     *
     * @param objectApiName  API name of the object (case-insensitive).
     * @param fields         Field API names to return. Id is always returned.
     * @param filters        Field name to value. Each entry becomes "field = value", joined with AND.
     *                       Values may be String, Boolean, Date, Datetime, Decimal, Integer, Long,
     *                       Double, Id or null.
     * @param orderByField   Optional field to sort ascending. Ignored when blank.
     * @param maxRows        Row limit, between 1 and 200 inclusive.
     * @return The matching records.
     * @throws SearchException on any validation or access failure.
     */
    public static List<SObject> search(String objectApiName, List<String> fields,
            Map<String, Object> filters, String orderByField, Integer maxRows) {

        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException('maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.');
        }

        Schema.DescribeSObjectResult objDescribe = describeObject(objectApiName);
        String objName = objDescribe.getName();
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // SELECT list: Id first, then requested fields in order, without duplicates.
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }
        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> seen = new Set<String>{ 'id' };
        for (String f : fields) {
            Schema.DescribeFieldResult fd = describeReadableField(fieldMap, f, objName);
            String canonical = fd.getName();
            if (seen.add(canonical.toLowerCase())) {
                selectFields.add(canonical);
            }
        }

        // WHERE clause: one equality condition per filter entry, values bound not inlined.
        List<String> conditions = new List<String>();
        Map<String, Object> binds = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            Integer idx = 0;
            for (String key : filters.keySet()) {
                Schema.DescribeFieldResult fd = describeReadableField(fieldMap, key, objName);
                if (!fd.isFilterable()) {
                    throw new SearchException('Field ' + fd.getName() + ' cannot be used as a filter.');
                }
                String bindName = 'f' + idx;
                idx++;
                conditions.add(fd.getName() + ' = :' + bindName);
                binds.put(bindName, toBindValue(fd, filters.get(key)));
            }
        }

        // ORDER BY: optional, ascending.
        String orderBy = null;
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult fd = describeReadableField(fieldMap, orderByField, objName);
            if (!fd.isSortable()) {
                throw new SearchException('Field ' + fd.getName() + ' cannot be used for sorting.');
            }
            orderBy = fd.getName();
        }

        // Assemble the query. Only canonical, validated names and an integer limit are inlined.
        String soql = 'SELECT ' + String.join(selectFields, ', ') + ' FROM ' + objName;
        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }
        if (orderBy != null) {
            soql += ' ORDER BY ' + orderBy + ' ASC';
        }
        soql += ' LIMIT ' + maxRows;

        try {
            return Database.queryWithBinds(soql, binds, System.AccessLevel.USER_MODE);
        } catch (QueryException e) {
            throw new SearchException('The search could not be completed: ' + e.getMessage());
        }
    }

    // ------------------------------------------------------------------
    // Validation helpers
    // ------------------------------------------------------------------

    private static Schema.DescribeSObjectResult describeObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }
        Schema.SObjectType sType = Schema.getGlobalDescribe().get(objectApiName.trim().toLowerCase());
        if (sType == null) {
            throw new SearchException('Object ' + objectApiName + ' does not exist.');
        }
        Schema.DescribeSObjectResult d = sType.getDescribe();
        if (!d.isAccessible()) {
            throw new SearchException('You do not have access to object ' + d.getName() + '.');
        }
        if (!d.isQueryable()) {
            throw new SearchException('Object ' + d.getName() + ' cannot be queried.');
        }
        return d;
    }

    /**
     * Resolves a field name case-insensitively and checks it is readable by the running user.
     */
    private static Schema.DescribeFieldResult describeReadableField(
            Map<String, Schema.SObjectField> fieldMap, String fieldName, String objName) {

        if (String.isBlank(fieldName)) {
            throw new SearchException('Field names cannot be blank.');
        }
        Schema.SObjectField sField = fieldMap.get(fieldName.trim().toLowerCase());
        if (sField == null) {
            throw new SearchException('Field ' + fieldName + ' is not a field of ' + objName + '.');
        }
        Schema.DescribeFieldResult d = sField.getDescribe();
        if (!d.isAccessible()) {
            throw new SearchException('You do not have access to field ' + d.getName() + '.');
        }
        return d;
    }

    // ------------------------------------------------------------------
    // Value coercion: convert UI values to the type the field expects
    // ------------------------------------------------------------------

    private static Object toBindValue(Schema.DescribeFieldResult fd, Object value) {
        if (value == null) {
            return null;
        }
        Schema.DisplayType t = fd.getType();
        String fname = fd.getName();

        if (t == Schema.DisplayType.BOOLEAN) {
            if (value instanceof Boolean) {
                return value;
            }
            String s = String.valueOf(value).trim().toLowerCase();
            if (s == 'true') {
                return true;
            }
            if (s == 'false') {
                return false;
            }
            throw new SearchException('Value for ' + fname + ' must be true or false.');
        }

        if (t == Schema.DisplayType.INTEGER || t == Schema.DisplayType.LONG) {
            Decimal d = toDecimal(fname, value);
            if (d != d.round(System.RoundingMode.DOWN)) {
                throw new SearchException('Value for ' + fname + ' must be a whole number.');
            }
            return (t == Schema.DisplayType.INTEGER) ? (Object) d.intValue() : (Object) d.longValue();
        }

        if (t == Schema.DisplayType.DOUBLE
                || t == Schema.DisplayType.CURRENCY
                || t == Schema.DisplayType.PERCENT
                || t == Schema.DisplayType.DECIMAL) {
            return toDecimal(fname, value);
        }

        if (t == Schema.DisplayType.DATE) {
            if (value instanceof Date) {
                return value;
            }
            if (value instanceof Datetime) {
                return ((Datetime) value).date();
            }
            try {
                return Date.valueOf(String.valueOf(value).trim());
            } catch (Exception e) {
                throw new SearchException('Value for ' + fname + ' must be a valid date (yyyy-MM-dd).');
            }
        }

        if (t == Schema.DisplayType.DATETIME) {
            if (value instanceof Datetime) {
                return value;
            }
            if (value instanceof Date) {
                Date dt = (Date) value;
                return Datetime.newInstance(dt.year(), dt.month(), dt.day());
            }
            try {
                return Datetime.valueOf(String.valueOf(value).trim());
            } catch (Exception e) {
                throw new SearchException('Value for ' + fname + ' must be a valid date/time.');
            }
        }

        if (t == Schema.DisplayType.ID || t == Schema.DisplayType.REFERENCE) {
            if (value instanceof Id) {
                return value;
            }
            try {
                return Id.valueOf(String.valueOf(value).trim());
            } catch (Exception e) {
                throw new SearchException('Value for ' + fname + ' must be a valid record Id.');
            }
        }

        // Text-like fields (String, Picklist, Email, Phone, URL, and so on).
        if (value instanceof String) {
            return value;
        }
        if (value instanceof Id || value instanceof Boolean || value instanceof Date
                || value instanceof Datetime || value instanceof Decimal
                || value instanceof Integer || value instanceof Long || value instanceof Double) {
            return String.valueOf(value);
        }
        throw new SearchException('Unsupported value type for field ' + fname + '.');
    }

    private static Decimal toDecimal(String fieldName, Object value) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        try {
            return Decimal.valueOf(String.valueOf(value).trim());
        } catch (Exception e) {
            throw new SearchException('Value for ' + fieldName + ' must be a valid number.');
        }
    }
