/**
 * Invocable action for Flow: finds an existing Contact by email address.
 *
 * - Returns exactly one Result per Request, in the same order.
 * - Email matching is case-insensitive and ignores leading/trailing spaces.
 * - Blank/null emails and emails with no matching contact return found = false.
 * - When several contacts share an email, the earliest created (CreatedDate, then Id) wins.
 * - Bulkified: at most one SOQL query per invocation, regardless of request count.
 * - Runs in sharing mode of the running user (with sharing).
 */
public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' description='Email address to search for' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the matching contact, if found')
        public Id contactId;

        @InvocableVariable(label='Found' description='True when a matching contact was found')
        public Boolean found;
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds the earliest-created existing contact matching the given email (case-insensitive).'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // 1. Normalize inputs (trim + lower-case) and collect distinct keys for a single query.
        List<String> keys = new List<String>(requests.size());
        Set<String> keysToQuery = new Set<String>();
        for (Integer i = 0; i < requests.size(); i++) {
            String key = normalizeKey(requests[i] == null ? null : requests[i].email);
            keys[i] = key;
            if (key != null) {
                keysToQuery.add(key);
            }
        }

        // 2. Single SOQL query (skipped entirely when there is nothing to look up).
        //    Ordering by CreatedDate then Id makes the first row per email the earliest contact.
        Map<String, Id> earliestContactByEmail = new Map<String, Id>();
        if (!keysToQuery.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :keysToQuery
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (c.Email == null) {
                    continue;
                }
                String k = c.Email.trim().toLowerCase();
                if (!earliestContactByEmail.containsKey(k)) {
                    earliestContactByEmail.put(k, c.Id);
                }
            }
        }

        // 3. Build one Result per request, preserving order.
        for (String key : keys) {
            Result r = new Result();
            r.found = false;
            r.contactId = null;

            if (key != null && earliestContactByEmail.containsKey(key)) {
                r.contactId = earliestContactByEmail.get(key);
                r.found = true;
            }
            results.add(r);
        }

        return results;
    }

    /**
     * Returns the trimmed, lower-cased email, or null when the input is blank.
     */
    private static String normalizeKey(String rawEmail) {
        if (String.isBlank(rawEmail)) {
            return null;
        }
        String trimmed = rawEmail.trim();
        return String.isBlank(trimmed) ? null : trimmed.toLowerCase();
    }
}
