/**
 * Parses e-commerce order JSON posted to an Apex REST endpoint and builds
 * an acknowledgement payload.
 *
 * All failures caused by the payload are reported as PayloadException.
 */
public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total;
    }

    private static final Integer MAX_INTEGER = 2147483647;

    /**
     * Parses a JSON order payload.
     *
     * @throws PayloadException for any invalid or unparseable payload.
     */
    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is empty.');
        }

        try {
            Object root = JSON.deserializeUntyped(body);

            if (!(root instanceof Map<String, Object>)) {
                throw new PayloadException('Request body must be a JSON object.');
            }
            Map<String, Object> doc = (Map<String, Object>) root;

            Order order = new Order();

            String orderNumber = toText(doc.get('number'));
            if (String.isBlank(orderNumber)) {
                throw new PayloadException('Missing or blank "number".');
            }
            order.orderNumber = orderNumber;

            order.orderDate = toDate(doc.get('date'));
            order.currencyCode = toText(doc.get('currency'));

            Object customerObj = doc.get('customer');
            if (customerObj instanceof Map<String, Object>) {
                Map<String, Object> customer = (Map<String, Object>) customerObj;
                order.customerEmail = toText(customer.get('email'));
            }

            Object linesObj = doc.get('lines');
            if (linesObj != null) {
                if (!(linesObj instanceof List<Object>)) {
                    throw new PayloadException('"lines" must be a JSON array.');
                }
                for (Object lineObj : (List<Object>) linesObj) {
                    order.lines.add(parseLine(lineObj));
                }
            }

            Decimal total = 0;
            for (Line line : order.lines) {
                total += line.lineTotal;
            }
            order.total = total.setScale(2, System.RoundingMode.HALF_UP);

            return order;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid order payload: ' + e.getMessage());
        }
    }

    /**
     * Builds the acknowledgement JSON object with exactly four keys:
     * number, status, lineCount and total.
     *
     * @throws PayloadException if the order is null.
     */
    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        if (order == null) {
            throw new PayloadException('Order must not be null.');
        }

        Integer lineCount = (order.lines == null) ? 0 : order.lines.size();
        Decimal total = (order.total == null) ? Decimal.valueOf(0) : order.total;

        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        gen.writeStringField('number', order.orderNumber);
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', lineCount);
        gen.writeNumberField('total', total);
        gen.writeEndObject();
        return gen.getAsString();
    }

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    private static Line parseLine(Object lineObj) {
        if (!(lineObj instanceof Map<String, Object>)) {
            throw new PayloadException('Each entry in "lines" must be a JSON object.');
        }
        Map<String, Object> m = (Map<String, Object>) lineObj;

        Line line = new Line();

        String sku = toText(m.get('sku'));
        if (String.isBlank(sku)) {
            throw new PayloadException('Line is missing "sku".');
        }
        line.sku = sku;

        Decimal qty = toNumber(m.get('quantity'), 'quantity');
        if (qty == null) {
            throw new PayloadException('Line is missing "quantity".');
        }
        if (qty <= 0) {
            throw new PayloadException('Line "quantity" must be positive.');
        }
        if (qty != qty.setScale(0, System.RoundingMode.DOWN)) {
            throw new PayloadException('Line "quantity" must be a whole number.');
        }
        if (qty > MAX_INTEGER) {
            throw new PayloadException('Line "quantity" is too large.');
        }
        line.quantity = qty.intValue();

        Decimal unitPrice = toNumber(m.get('unitPrice'), 'unitPrice');
        if (unitPrice == null) {
            throw new PayloadException('Line is missing "unitPrice".');
        }
        if (unitPrice < 0) {
            throw new PayloadException('Line "unitPrice" must not be negative.');
        }
        line.unitPrice = unitPrice;

        Decimal discount = toNumber(m.get('discount'), 'discount');
        if (discount == null) {
            discount = 0;
        }
        if (discount < 0 || discount > 1) {
            throw new PayloadException('Line "discount" must be between 0 and 1.');
        }
        line.discount = discount;

        line.lineTotal = (qty * unitPrice * (1 - discount))
            .setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    /** Returns the value as text for strings and primitives; null for null. */
    private static String toText(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        if (value instanceof Map<String, Object> || value instanceof List<Object>) {
            throw new PayloadException('Expected a scalar value but found an object or array.');
        }
        return String.valueOf(value);
    }

    /** Returns the value as Decimal for numeric JSON values; null for null. */
    private static Decimal toNumber(Object value, String fieldName) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer || value instanceof Long) {
            return Decimal.valueOf(String.valueOf(value));
        }
        throw new PayloadException('"' + fieldName + '" must be a number.');
    }

    /** Parses a strict ISO yyyy-MM-dd date; null for null or missing values. */
    private static Date toDate(Object value) {
        String s = toText(value);
        if (s == null) {
            return null;
        }
        if (!Pattern.matches('\\d{4}-\\d{2}-\\d{2}', s)) {
            throw new PayloadException('"date" must use the format yyyy-MM-dd.');
        }
        String[] parts = s.split('-');
        Integer y = Integer.valueOf(parts[0]);
        Integer m = Integer.valueOf(parts[1]);
        Integer d = Integer.valueOf(parts[2]);
        if (m < 1 || m > 12 || d < 1 || d > 31) {
            throw new PayloadException('"date" is not a valid calendar date.');
        }
        Date result = Date.newInstance(y, m, d);
        if (result.month() != m || result.day() != d) {
            throw new PayloadException('"date" is not a valid calendar date.');
        }
        return result;
    }
}
