public with sharing class PicklistService {

    /**
     * A single active picklist value.
     */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * Raised for invalid input or metadata problems (blank names, unknown object or
     * field, or a field that is not a picklist or multi-select picklist).
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of a picklist or multi-select picklist field, in the
     * order they are defined on the field. Object and field API names are
     * case-insensitive and may be standard or custom.
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name is required.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name is required.');
        }

        String objName = objectApiName.trim().toLowerCase();
        String fieldName = fieldApiName.trim().toLowerCase();

        // Global describe keys are lowercase API names
        Schema.SObjectType sObjType = Schema.getGlobalDescribe().get(objName);
        if (sObjType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        Map<String, Schema.SObjectField> fieldMap = sObjType.getDescribe().fields.getMap();
        Schema.SObjectField sObjField = fieldMap.get(fieldName);
        if (sObjField == null) {
            throw new PicklistServiceException(
                'Field ' + fieldApiName + ' does not exist on object ' + objectApiName + '.'
            );
        }

        Schema.DescribeFieldResult dfr = sObjField.getDescribe();
        Schema.DisplayType dt = dfr.getType();
        if (dt != Schema.DisplayType.PICKLIST && dt != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field ' + fieldApiName + ' on ' + objectApiName +
                ' is not a picklist or multi-select picklist.'
            );
        }

        List<Option> options = new List<Option>();
        // getPicklistValues() preserves the order defined on the field
        for (Schema.PicklistEntry entry : dfr.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
            }
        }
        return options;
    }
}
