public with sharing class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds.clone();
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer first so that the outcome of this job is always logged
        // and failed runs can be retried, whatever happens below.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        if (accountIds.isEmpty()) {
            return;
        }

        List<Account> accounts = [
            SELECT Id, Description
            FROM Account
            WHERE Id IN :accountIds
        ];

        for (Account acc : accounts) {
            acc.Description = 'Synced to ERP';
        }

        // Deliberately not caught: a DmlException fails the job and the platform
        // rolls back all changes made by this transaction (all-or-nothing).
        update accounts;
    }
}
