public with sharing class ErpSyncFinalizer implements Finalizer {

    private static final String JOB_NAME = 'ErpAccountSyncJob';
    private static final Integer MAX_ATTEMPTS = 3;
    private static final Integer ERROR_MAX_LENGTH = 255;

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds.clone();
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext ctx) {
        Boolean succeeded = (ctx.getResult() == ParentJobResult.SUCCESS);

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Attempt__c = attempt
        );

        if (succeeded) {
            jobLog.Status__c = 'Success';
        } else {
            jobLog.Status__c = 'Failed';
            Exception ex = ctx.getException();
            jobLog.Error__c = truncate(ex == null ? null : ex.getMessage());
        }

        insert jobLog;

        if (!succeeded && attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }

    private static String truncate(String value) {
        if (value == null) {
            return null;
        }
        return value.length() > ERROR_MAX_LENGTH
            ? value.substring(0, ERROR_MAX_LENGTH)
            : value;
    }
}
