```apex
/**
 * Keeps Account.FB_Open_Pipeline__c and Account.FB_Open_Opportunities__c in sync
 * with the account's open (IsClosed = false) opportunities.
 *
 * Design:
 * - Totals are always recalculated from the database with an aggregate query, never
 *   incrementally. SOQL in an after trigger sees the effects of earlier DML in the same
 *   transaction, so repeated DML on the same records stays correct.
 * - Only accounts whose stored values differ from the recalculated values are updated.
 *   This prevents recursion with the legacy AccountTrigger, which updates open
 *   opportunities whenever an account is updated.
 * - Opportunity updates that do not touch a field that affects the totals are ignored.
 * - "without sharing" is deliberate: totals must include every open opportunity of the
 *   account, regardless of the running user's sharing access.
 */
public without sharing class OpportunityPipelineHandler {

    public static void handleInsert(List<Opportunity> newList) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newList) {
            addId(accountIds, opp.AccountId);
        }
        recalculate(accountIds);
    }

    public static void handleUpdate(List<Opportunity> newList, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newList) {
            Opportunity oldOpp = oldMap.get(opp.Id);
            if (oldOpp == null) {
                addId(accountIds, opp.AccountId);
                continue;
            }
            Boolean relevantChange =
                opp.AccountId != oldOpp.AccountId ||
                opp.Amount != oldOpp.Amount ||
                opp.IsClosed != oldOpp.IsClosed ||
                opp.StageName != oldOpp.StageName;
            if (relevantChange) {
                // Covers moves between accounts: both the old and the new account change.
                addId(accountIds, oldOpp.AccountId);
                addId(accountIds, opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public static void handleDelete(List<Opportunity> oldList) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : oldList) {
            addId(accountIds, opp.AccountId);
        }
        recalculate(accountIds);
    }

    public static void handleUndelete(List<Opportunity> newList) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newList) {
            addId(accountIds, opp.AccountId);
        }
        recalculate(accountIds);
    }

    // -------------------------------------------------------------------------

    private static void addId(Set<Id> accountIds, Id accountId) {
        if (accountId != null) {
            accountIds.add(accountId);
        }
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Aggregate the open pipeline per account. Accounts with no open opportunities
        // do not appear in the result and are handled as 0 / 0 below.
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();

        for (AggregateResult ar : [
            SELECT AccountId accId, SUM(Amount) pipe, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Decimal pipe = (Decimal) ar.get('pipe');
            Integer cnt = (Integer) ar.get('cnt');
            pipelineByAccount.put(accId, pipe == null ? 0 : pipe);
            countByAccount.put(accId, cnt == null ? 0 : cnt);
        }

        List<Account> toUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newPipeline = pipelineByAccount.containsKey(acc.Id) ? pipelineByAccount.get(acc.Id) : 0;
            Integer newCount = countByAccount.containsKey(acc.Id) ? countByAccount.get(acc.Id) : 0;

            // Compare with stored values; null stored values count as different so they get initialised.
            if (acc.FB_Open_Pipeline__c != newPipeline || acc.FB_Open_Opportunities__c != newCount) {
                toUpdate.add(new Account(
                    Id = acc.Id,
                    FB_Open_Pipeline__c = newPipeline,
                    FB_Open_Opportunities__c = newCount
                ));
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
