```apex
/**
 * Rolls up closed-won Opportunity Amount per Account for the current calendar year.
 *
 * - Uses a single aggregate SOQL (SUM ... GROUP BY AccountId) per chunk; no opportunity
 *   records are loaded into memory.
 * - "with sharing" and "WITH USER_MODE" make the query respect the running user's
 *   record sharing and field-level security.
 * - Every non-null requested Account Id is a key in the result, defaulting to 0.
 * - Requested ids are chunked so each aggregate query returns at most CHUNK_SIZE groups,
 *   staying safely under the 2,000-row aggregate query result limit.
 */
public with sharing class OpportunityRollupService {

    private static final Integer CHUNK_SIZE = 2000;

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Normalise: drop nulls and de-duplicate, then default every requested id to 0.
        Set<Id> requested = new Set<Id>();
        for (Id accId : accountIds) {
            if (accId != null) {
                requested.add(accId);
            }
        }
        if (requested.isEmpty()) {
            return result;
        }
        for (Id accId : requested) {
            result.put(accId, 0);
        }

        List<Id> idList = new List<Id>(requested);
        for (Integer start = 0; start < idList.size(); start += CHUNK_SIZE) {
            Integer finish = Math.min(start + CHUNK_SIZE, idList.size());

            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < finish; i++) {
                chunk.add(idList[i]);
            }

            List<AggregateResult> rows = [
                SELECT AccountId acc, SUM(Amount) total
                FROM Opportunity
                WHERE AccountId IN :chunk
                  AND IsWon = true
                  AND CloseDate = THIS_YEAR
                WITH USER_MODE
                GROUP BY AccountId
            ];

            for (AggregateResult ar : rows) {
                Id accId = (Id) ar.get('acc');
                // SUM over all-blank Amounts yields null; keep the 0 default in that case.
                Decimal total = (Decimal) ar.get('total');
                if (accId != null && requested.contains(accId) && total != null) {
                    result.put(accId, total);
                }
            }
        }

        return result;
    }
}
```

