public class Opportunities extends fflib_SObjectDomain {

    public static final String CLOSED_WON = 'Closed Won';

    public Opportunities(List<SObject> sObjectList) {
        super(sObjectList);
    }

    public override void onAfterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (SObject record : Records) {
            Opportunity opp = (Opportunity) record;
            if (opp.StageName == CLOSED_WON) {
                qualifyingIds.add(opp.Id);
            }
        }
        startFulfilmentIfAny(qualifyingIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Set<Id> qualifyingIds = new Set<Id>();
        for (SObject record : Records) {
            Opportunity opp = (Opportunity) record;
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (opp.StageName == CLOSED_WON && oldOpp != null && oldOpp.StageName != CLOSED_WON) {
                qualifyingIds.add(opp.Id);
            }
        }
        startFulfilmentIfAny(qualifyingIds);
    }

    private static void startFulfilmentIfAny(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return;
        }
        IOpportunityFulfilmentService service =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
        service.startFulfilment(opportunityIds);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }
}
