```apex
/**
 * Creates Accounts and their Contacts in a single fflib Unit of Work.
 *
 * Input: map of Account name -> list of Contact last names.
 * For each entry one Account is created, and one Contact per last name is
 * linked to it. All inserts go through one fflib_SObjectUnitOfWork commit.
 * The UoW orders inserts by the object types listed in its constructor, so
 * Accounts are written before Contacts and the Contact AccountId is set from
 * the parent Account Id after the Account insert.
 */
public with sharing class AccountOnboardingService {

    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> createdAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return createdAccounts;
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{ Account.SObjectType, Contact.SObjectType }
        );

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account newAccount = new Account(Name = accountName);
            uow.registerNew(newAccount);
            createdAccounts.add(newAccount);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                Contact newContact = new Contact(LastName = lastName);
                // Registers the Contact as a child of newAccount; AccountId is
                // populated from the Account Id during commitWork().
                uow.registerNew(newContact, Contact.AccountId, newAccount);
            }
        }

        // Single commit for all Accounts and Contacts. Record Ids are populated
        // on the same instances held in createdAccounts.
        uow.commitWork();

        return createdAccounts;
    }
}
