        // Collect the distinct parent account Ids from the whole batch.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // One query for the whole batch, regardless of how many cases were inserted.
        Set<Id> hotAccountIds = new Map<Id, Account>(
            [SELECT Id FROM Account WHERE Id IN :accountIds AND Rating = :HOT_RATING]
        ).keySet();
        if (hotAccountIds.isEmpty()) {
            return;
        }

        // Cases without an account, or with a non-Hot account, keep their Priority unchanged.
        for (Case c : newCases) {
            if (c.AccountId != null && hotAccountIds.contains(c.AccountId)) {
                c.Priority = HIGH_PRIORITY;
            }
        }
    }
}
