```apex
/**
 * Pushes newly created Accounts to the ERP as customers.
 *
 * Triggers cannot perform callouts synchronously, so the work is handed to a
 * Queueable that implements Database.AllowsCallouts. Accounts are grouped into
 * chunks of at most MAX_CUSTOMERS_PER_REQUEST, and each chunk is sent as one
 * POST whose JSON array contains one element per account. This keeps the
 * per-account traceability the ERP team needs while staying within the
 * callout limit (100 per transaction) and the queueable enqueue limit (50 per
 * transaction) for bulk inserts.
 */
public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    public static final Integer MAX_CUSTOMERS_PER_REQUEST = 200;
    private static final String ENDPOINT = 'callout:ERP/api/customers';

    private final List<CustomerPayload> customers;

    public class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;
    }

    private ErpCustomerSync(List<CustomerPayload> customers) {
        this.customers = customers;
    }

    /**
     * Entry point called from AccountTrigger (after insert).
     * Builds ERP payloads for the new accounts and enqueues one job per chunk.
     */
    public static void enqueueAccounts(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<CustomerPayload> payloads = new List<CustomerPayload>();
        for (Account acc : newAccounts) {
            if (acc.Id == null) {
                continue;
            }
            CustomerPayload p = new CustomerPayload();
            p.salesforceId = String.valueOf(acc.Id);
            p.name = acc.Name;
            p.country = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;
            payloads.add(p);
        }

        for (Integer start = 0; start < payloads.size(); start += MAX_CUSTOMERS_PER_REQUEST) {
            Integer finish = Math.min(start + MAX_CUSTOMERS_PER_REQUEST, payloads.size());
            List<CustomerPayload> chunk = new List<CustomerPayload>();
            for (Integer i = start; i < finish; i++) {
                chunk.add(payloads[i]);
            }

            if (Limits.getQueueableJobs() >= Limits.getLimitQueueableJobs()) {
                System.debug(LoggingLevel.ERROR,
                    'ErpCustomerSync: queueable limit reached, ' + (payloads.size() - start) +
                    ' account(s) not sent to ERP.');
                break;
            }
            System.enqueueJob(new ErpCustomerSync(chunk));
        }
    }

    public void execute(QueueableContext context) {
        if (customers == null || customers.isEmpty()) {
            return;
        }

        HttpRequest req = new HttpRequest();
        req.setEndpoint(ENDPOINT);
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(customers, false));

        HttpResponse res = new Http().send(req);

        if (res.getStatusCode() < 200 || res.getStatusCode() > 299) {
            System.debug(LoggingLevel.ERROR,
                'ErpCustomerSync: ERP returned HTTP ' + res.getStatusCode() +
                ' for ' + customers.size() + ' customer(s). Body: ' + res.getBody());
        }
    }
}
```

