public without sharing class CaseSurveyJob implements Queueable {

    private final Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = (caseIds == null) ? new Set<Id>() : caseIds.clone();
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        // Re-check current state: the case may have been reopened or changed
        // between the trigger firing and this job running.
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
              AND IsClosed = true
              AND ContactId != null
        ];

        if (cases.isEmpty()) {
            return;
        }

        Date surveyDate = Date.today().addDays(2);
        List<Task> tasks = new List<Task>();
        List<String> caseNumbers = new List<String>();

        for (Case c : cases) {
            tasks.add(new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = surveyDate,
                Status       = 'Not Started'
            ));
            caseNumbers.add(c.CaseNumber);
        }

        // allOrNone = false: one failing record must not block the others.
        Database.SaveResult[] results = Database.insert(tasks, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'CaseSurveyJob: failed to create survey task for case ' +
                        caseNumbers[i] + ': ' + err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }
    }
}
