```apex
/**
 * Keeps Contact.MailingCountry in step with Account.BillingCountry when an
 * account's billing country changes (for example, a headquarters move).
 *
 * Rules:
 *  - Only accounts whose BillingCountry changed to a non-blank value are processed.
 *  - Only contacts whose MailingCountry is blank, or equal to the account's
 *    previous BillingCountry, are updated.
 *  - Contacts with any other MailingCountry (for example, those who work abroad)
 *    are left unchanged.
 *
 * Bulk safety: the contact query is restricted to the changed accounts and runs
 * once per trigger invocation. It never scans the full Contact table, which
 * would exceed governor limits in an org with millions of contacts.
 */
public with sharing class AccountCountrySync {

    public static void onAfterUpdate(List<Account> newAccounts, Map<Id, Account> oldMap) {
        if (newAccounts == null || newAccounts.isEmpty() || oldMap == null) {
            return;
        }

        // Accounts whose BillingCountry changed to a non-blank value.
        Map<Id, String> newCountryByAccountId = new Map<Id, String>();
        Map<Id, String> oldCountryByAccountId = new Map<Id, String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldMap.get(acc.Id);
            if (oldAcc == null) {
                continue;
            }
            if (acc.BillingCountry == oldAcc.BillingCountry) {
                continue;
            }
            if (String.isBlank(acc.BillingCountry)) {
                continue;
            }
            newCountryByAccountId.put(acc.Id, acc.BillingCountry);
            oldCountryByAccountId.put(acc.Id, oldAcc.BillingCountry);
        }

        if (newCountryByAccountId.isEmpty()) {
            return;
        }

        // Single query, bounded to the contacts of the changed accounts only.
        List<Contact> contacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :newCountryByAccountId.keySet()
        ];

        List<Contact> toUpdate = new List<Contact>();
        for (Contact c : contacts) {
            String previousBilling = oldCountryByAccountId.get(c.AccountId);
            String newBilling = newCountryByAccountId.get(c.AccountId);

            // Leave contacts that work in another country untouched.
            Boolean blankMailing = String.isBlank(c.MailingCountry);
            Boolean followsOldBilling = c.MailingCountry == previousBilling;

            if (blankMailing || followsOldBilling) {
                c.MailingCountry = newBilling;
                toUpdate.add(c);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
