import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

const FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    @api recordId;

    record;
    error;

    // Reactive wire: when recordId changes (e.g. a reused console tab),
    // the adapter is re-provisioned and the new record is loaded.
    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredRecord({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        }
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get hasRecord() {
        return !!this.record && !this.error;
    }

    get hasError() {
        return !!this.error;
    }

    get errorMessage() {
        return this.error?.body?.message || this.error?.message || 'An unknown error occurred.';
    }

    get accountName() {
        return this.record?.fields?.Name?.value ?? '';
    }

    get industry() {
        return this.record?.fields?.Industry?.value ?? null;
    }

    get hasIndustry() {
        return !!this.industry;
    }

    get annualRevenue() {
        return this.record?.fields?.AnnualRevenue?.value ?? null;
    }

    get ownerName() {
        return this.record?.fields?.Owner?.value?.fields?.Name?.value ?? '';
    }
}
