import { LightningElement, api } from 'lwc';

/**
 * Displays a list of an Account's contacts.
 * Data is supplied by the parent; this component performs no fetching.
 */
export default class AccountContactList extends LightningElement {
    /**
     * Array of { Id, Name, Title } objects owned by the parent.
     * Title is optional. Reassigning this property re-renders the component.
     * @type {Array<{Id: string, Name: string, Title?: string}>}
     */
    @api contacts;

    /** True when contacts is a non-empty array. */
    get hasContacts() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    /** Count label: "1 contact" for exactly one, otherwise "<n> contacts". */
    get countLabel() {
        const count = this.hasContacts ? this.contacts.length : 0;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    /**
     * Contacts sorted by Name ascending, as view models for the template.
     * Works on a copy so the parent's array is never mutated.
     */
    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }

        return [...this.contacts]
            .sort((a, b) =>
                String(a.Name ?? '').localeCompare(String(b.Name ?? ''))
            )
            .map((contact) => {
                const title = contact.Title ? String(contact.Title).trim() : '';
                return {
                    Id: contact.Id,
                    Name: contact.Name,
                    Title: title,
                    hasTitle: title.length > 0
                };
            });
    }
}
