import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage;

    _timeoutId;
    // Incremented for every request issued and every cancellation/teardown.
    // A response is applied only if it belongs to the most recent request.
    _requestId = 0;

    get hasResults() {
        return this.contacts.length > 0;
    }

    handleChange(event) {
        const term = (event.target.value || '').trim();

        // Any new keystroke supersedes a pending debounce.
        this.clearPendingTimer();

        if (term.length < MIN_SEARCH_LENGTH) {
            // Too short: cancel any in-flight request and clear results. No Apex call.
            this.cancelOutstandingRequests();
            this.contacts = [];
            this.errorMessage = undefined;
            return;
        }

        this._timeoutId = setTimeout(() => {
            this._timeoutId = undefined;
            this.runSearch(term);
        }, DEBOUNCE_MS);
    }

    runSearch(searchTerm) {
        const requestId = ++this._requestId;

        searchContacts({ searchTerm })
            .then((result) => {
                if (requestId !== this._requestId) {
                    // Stale response (newer request issued, cancelled, or component removed).
                    return;
                }
                this.contacts = result || [];
                this.errorMessage = undefined;
            })
            .catch((error) => {
                if (requestId !== this._requestId) {
                    return;
                }
                this.contacts = [];
                this.errorMessage =
                    (error && error.body && error.body.message) || 'An unexpected error occurred.';
            });
    }

    disconnectedCallback() {
        // Prevent a pending search from running after removal and ignore any in-flight responses.
        this.clearPendingTimer();
        this.cancelOutstandingRequests();
    }

    clearPendingTimer() {
        if (this._timeoutId !== undefined) {
            clearTimeout(this._timeoutId);
            this._timeoutId = undefined;
        }
    }

    cancelOutstandingRequests() {
        this._requestId++;
    }
}
