import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import LightningConfirm from 'lightning/confirm';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const OBJECT_API_NAME = 'Opportunity';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text' },
    { label: 'Stage', fieldName: 'StageName', type: 'text' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    _rows = [];

    /**
     * Array of { Id, Name, StageName, Amount } supplied by the parent.
     * The component keeps its own shallow copy so the parent's array and
     * objects are never mutated. A new array from the parent replaces the table data.
     */
    @api
    get opportunities() {
        return this._rows;
    }
    set opportunities(value) {
        this._rows = Array.isArray(value) ? value.map((row) => ({ ...row })) : [];
    }

    columns = COLUMNS;

    get rows() {
        return this._rows;
    }

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this.navigateToRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToRecord(row.Id, 'edit');
                break;
            case 'delete':
                this.confirmAndDelete(row);
                break;
            default:
                break;
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId,
                objectApiName: OBJECT_API_NAME,
                actionName
            }
        });
    }

    async confirmAndDelete(row) {
        let confirmed = false;
        try {
            confirmed = await LightningConfirm.open({
                message: `Are you sure you want to delete "${row.Name}"?`,
                label: 'Delete Opportunity',
                theme: 'error'
            });
        } catch (error) {
            // Confirmation dialog was dismissed or failed: treat as cancel.
            return;
        }

        if (!confirmed) {
            return;
        }

        try {
            await deleteRecord(row.Id);
            this._rows = this._rows.filter((item) => item.Id !== row.Id);
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Delete failed',
                    message: error?.body?.message,
                    variant: 'error'
                })
            );
        }
    }
}
