export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } rendered in the given order. */
    @api lines = [];

    showError = false;

    /** Child editors in DOM (display) order. */
    getEditors() {
        return Array.from(this.template.querySelectorAll('c-line-item-editor'));
    }

    handleReset() {
        this.getEditors().forEach((editor) => editor.reset());
    }

    handleSubmit() {
        // map (not some/every with short-circuit) so that every editor is
        // validated and all invalid lines show their errors at once.
        const editors = this.getEditors();
        const results = editors.map((editor) => editor.validate());
        const allValid = results.every((valid) => Boolean(valid));

        if (!allValid) {
            this.showError = true;
            return;
        }

        this.showError = false;
        const values = editors.map((editor) => editor.getValue());
        this.dispatchEvent(new CustomEvent('submit', {
            detail: { lines: values }
        }));
    }
}
