import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    hasStats = false;
    errorMessage;

    // Token identifying the request currently in flight (null when idle).
    // Used both as the "in flight" guard and to discard responses from
    // requests that were started before a disconnect.
    inFlightToken = null;
    timerId = null;

    // Arrow function so the same reference can be passed to removeEventListener.
    handleVisibilityChange = () => {
        if (document.visibilityState === 'hidden') {
            this.stopTimer();
        } else {
            this.refresh();
            this.startTimer();
        }
    };

    connectedCallback() {
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
        if (document.visibilityState !== 'hidden') {
            this.refresh();
            this.startTimer();
        }
    }

    disconnectedCallback() {
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
        this.stopTimer();
        // Invalidate any pending request so its late response is ignored
        // and does not block a future insertion.
        this.inFlightToken = null;
    }

    startTimer() {
        this.stopTimer(); // guarantees only one polling loop at a time
        this.timerId = setInterval(() => this.poll(), REFRESH_INTERVAL_MS);
    }

    stopTimer() {
        if (this.timerId !== null) {
            clearInterval(this.timerId);
            this.timerId = null;
        }
    }

    poll() {
        if (document.visibilityState === 'hidden') {
            return;
        }
        this.refresh();
    }

    refresh() {
        // Never start a request while the previous one is still in flight.
        if (this.inFlightToken) {
            return;
        }

        const token = {};
        this.inFlightToken = token;

        getQueueStats()
            .then((result) => {
                if (this.inFlightToken !== token) {
                    return; // stale response from before a disconnect
                }
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.hasStats = true;
                this.errorMessage = undefined;
            })
            .catch((error) => {
                if (this.inFlightToken !== token) {
                    return;
                }
                this.errorMessage =
                    error?.body?.message ??
                    error?.message ??
                    'Unable to load queue statistics.';
            })
            .finally(() => {
                if (this.inFlightToken === token) {
                    this.inFlightToken = null;
                }
            });
    }
}
