import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
const PERSONAL_EMAIL_MESSAGE = 'Use your work email address.';

export default class EventRegistrationForm extends LightningElement {
    values = {
        fullName: '',
        email: '',
        company: ''
    };

    isSubmitting = false;

    handleChange(event) {
        const field = event.target.dataset.field;
        if (Object.prototype.hasOwnProperty.call(this.values, field)) {
            this.values[field] = event.detail.value;
        }
    }

    async handleRegister() {
        if (this.isSubmitting) {
            return;
        }

        // 1. Work-email rule, applied before any validity reporting.
        const emailInput = this.template.querySelector('[data-field="email"]');
        emailInput.setCustomValidity(
            this.isPersonalEmail(this.values.email) ? PERSONAL_EMAIL_MESSAGE : ''
        );

        // 2. Report every input so all invalid fields show messages at once.
        //    map() runs for every element before every() evaluates the results.
        const inputs = Array.from(this.template.querySelectorAll('[data-field]'));
        const allValid = inputs
            .map((input) => input.reportValidity())
            .every((isValid) => isValid);

        // 3. Stop if anything is invalid.
        if (!allValid) {
            return;
        }

        this.isSubmitting = true;
        try {
            // 4. Success path.
            await register({
                fullName: this.values.fullName,
                email: this.values.email,
                company: this.values.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error?.body?.message,
                    variant: 'error'
                })
            );
        } finally {
            this.isSubmitting = false;
        }
    }

    isPersonalEmail(email) {
        const trimmed = (email || '').trim();
        const atIndex = trimmed.lastIndexOf('@');
        if (atIndex < 0) {
            return false;
        }
        const domain = trimmed.slice(atIndex + 1).toLowerCase();
        return PERSONAL_EMAIL_DOMAINS.includes(domain);
    }
}
