import { LightningElement, api } from 'lwc';

// Unique per-instance prefix so option ids never collide across multiple listboxes on a page.
let instanceCounter = 0;

// The only keys this component handles. Every other key (including Tab) keeps its default behaviour.
const HANDLED_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' ']);

export default class StatusListbox extends LightningElement {
    /** Accessible name of the listbox (rendered as aria-label). */
    @api label;

    _uid;
    _options = [];
    _value;
    _activeIndex = -1;

    constructor() {
        super();
        instanceCounter += 1;
        this._uid = `status-listbox-${instanceCounter}`;
    }

    /**
     * Array of { value, label }.
     */
    @api
    get options() {
        return this._options;
    }
    set options(newOptions) {
        this._options = Array.isArray(newOptions) ? newOptions : [];
        // Keep the active option valid for the new list.
        if (this._activeIndex < 0 || this._activeIndex >= this._options.length) {
            this._activeIndex = this.defaultActiveIndex();
        }
    }

    /**
     * Selected value (may be empty). Parent may change it at any time;
     * the active option moves to the new selection.
     */
    @api
    get value() {
        return this._value;
    }
    set value(newValue) {
        this._value = newValue;
        this._activeIndex = this.defaultActiveIndex();
    }

    // ---- Derived state -------------------------------------------------

    /** Index of the option matching the current value, or -1 if none. */
    get selectedIndex() {
        if (this._value === undefined || this._value === null) {
            return -1;
        }
        return this._options.findIndex((option) => option.value === this._value);
    }

    /** Where the active option should be when nothing else dictates it. */
    defaultActiveIndex() {
        const selected = this.selectedIndex;
        if (selected >= 0) {
            return selected;
        }
        return this._options.length > 0 ? 0 : -1;
    }

    get renderedOptions() {
        const selected = this.selectedIndex;
        return this._options.map((option, index) => {
            const isSelected = index === selected;
            const isActive = index === this._activeIndex;
            return {
                id: `${this._uid}-option-${index}`,
                value: option.value,
                label: option.label,
                ariaSelected: isSelected ? 'true' : 'false',
                isActive,
                className: isActive ? 'option option-active' : 'option'
            };
        });
    }

    get activeId() {
        if (this._activeIndex < 0 || this._activeIndex >= this._options.length) {
            return undefined;
        }
        return `${this._uid}-option-${this._activeIndex}`;
    }

    // ---- Event handlers ------------------------------------------------

    handleKeyDown(event) {
        const key = event.key;
        if (!HANDLED_KEYS.has(key)) {
            return;
        }
        // Only the six handled keys get preventDefault().
        event.preventDefault();

        const count = this._options.length;
        if (count === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(this._activeIndex + 1, count - 1);
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = count - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this._activeIndex);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const id = event.currentTarget.id;
        const index = this.renderedOptions.findIndex((option) => option.id === id);
        if (index < 0) {
            return;
        }
        this._activeIndex = index;
        this.selectOption(index);
    }

    // ---- Helpers -------------------------------------------------------

    /**
     * Selects the option at `index`. Dispatches `change` only if it was not already selected.
     */
    selectOption(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        if (index === this.selectedIndex) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
