import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    // Private, component-owned copy of the task list.
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this.items;
    }

    set tasks(value) {
        // Work on a copy so the parent's array and task objects are never modified.
        this.items = Array.isArray(value)
            ? value
                  .filter((task) => task && typeof task === 'object')
                  .map((task) => ({ ...task }))
            : [];
    }

    get displayHeading() {
        // Display only: the public `heading` value is left untouched.
        return this.heading ? String(this.heading).toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }

        const task = { id: this.generateId(), label, done: false };
        this.items = [...this.items, task];
        this.newLabel = '';

        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done: !task.done } : task
        );
    }

    generateId() {
        const existing = new Set(this.items.map((task) => String(task.id)));
        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (existing.has(id));
        return id;
    }
}
