/**
 * Sets each contact's current employer as their NPSP primary affiliation.
 *
 * Bulk budget: 2 SOQL (contacts, affiliations) and 2 DML (affiliation upsert, contact update).
 *
 * For each contact whose primary employer changes:
 *  - the previous primary affiliation is set to Former, non-primary, with EndDate = today;
 *  - an existing Current affiliation to the new organization is reused (set primary) to avoid
 *    duplicates, otherwise a new Current primary affiliation is inserted;
 *  - Contact.npsp__Primary_Affiliation__c is pointed at the new organization.
 * Contacts whose organization is already a Current primary affiliation are left untouched.
 * The household account (Contact.AccountId) is never modified.
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Normalise input, dropping null keys/values.
        Map<Id, Id> targets = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId != null && orgId != null) {
                targets.put(contactId, orgId);
            }
        }
        if (targets.isEmpty()) {
            return;
        }

        // SOQL 1: contacts and their current primary affiliation lookup.
        Map<Id, Contact> contactsById = new Map<Id, Contact>(
            [SELECT Id, npsp__Primary_Affiliation__c
               FROM Contact
              WHERE Id IN :targets.keySet()]
        );

        // SOQL 2: affiliations that are Current or flagged primary, for all target contacts.
        Map<Id, List<npe5__Affiliation__c>> affsByContact = new Map<Id, List<npe5__Affiliation__c>>();
        for (npe5__Affiliation__c aff : [
                SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                       npe5__Primary__c, npe5__StartDate__c, npe5__EndDate__c
                  FROM npe5__Affiliation__c
                 WHERE npe5__Contact__c IN :targets.keySet()
                   AND (npe5__Status__c = 'Current' OR npe5__Primary__c = true)
        ]) {
            if (!affsByContact.containsKey(aff.npe5__Contact__c)) {
                affsByContact.put(aff.npe5__Contact__c, new List<npe5__Affiliation__c>());
            }
            affsByContact.get(aff.npe5__Contact__c).add(aff);
        }

        Date today = Date.today();
        List<npe5__Affiliation__c> affsToUpsert = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Id contactId : targets.keySet()) {
            Contact c = contactsById.get(contactId);
            if (c == null) {
                continue; // contact not found or not visible to this user
            }
            Id orgId = targets.get(contactId);
            List<npe5__Affiliation__c> existing = affsByContact.containsKey(contactId)
                ? affsByContact.get(contactId)
                : new List<npe5__Affiliation__c>();

            // Find an existing affiliation to the target org.
            npe5__Affiliation__c target = null;
            Boolean alreadyPrimary = false;
            for (npe5__Affiliation__c aff : existing) {
                if (aff.npe5__Organization__c != orgId) {
                    continue;
                }
                if (aff.npe5__Primary__c == true && aff.npe5__Status__c == 'Current') {
                    alreadyPrimary = true;
                } else if (target == null && aff.npe5__Status__c == 'Current') {
                    target = aff;
                }
            }

            if (alreadyPrimary) {
                continue; // nothing to change for this contact
            }

            // Demote previous primary affiliation(s) to Former, non-primary, ended today.
            for (npe5__Affiliation__c aff : existing) {
                if (aff.npe5__Primary__c == true && aff.npe5__Organization__c != orgId) {
                    aff.npe5__Primary__c = false;
                    aff.npe5__Status__c = 'Former';
                    aff.npe5__EndDate__c = today;
                    affsToUpsert.add(aff);
                }
            }

            // Reuse a Current affiliation to the org if one exists, otherwise create one.
            if (target == null) {
                target = new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__StartDate__c = today
                );
            }
            target.npe5__Status__c = 'Current';
            target.npe5__Primary__c = true;
            target.npe5__EndDate__c = null;
            affsToUpsert.add(target);

            // Point the contact's primary affiliation lookup at the new organization.
            if (c.npsp__Primary_Affiliation__c != orgId) {
                contactsToUpdate.add(new Contact(
                    Id = contactId,
                    npsp__Primary_Affiliation__c = orgId
                ));
            }
        }

        // DML 1: affiliations (demoted previous primaries, reused and new current primaries).
        if (!affsToUpsert.isEmpty()) {
            upsert affsToUpsert;
        }

        // DML 2: contact primary affiliation lookups.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
