/**
 * Replaces the GAU allocations on an Opportunity with percentage-based allocations.
 *
 * Allocations are stored as npsp__Percent__c only (npsp__Amount__c is left blank).
 * NPSP calculates each allocation's amount from the opportunity amount, so when the
 * opportunity amount changes later the allocation amounts follow it automatically.
 *
 * All validation runs before any data is changed. The delete and insert run in one
 * savepoint so a failed insert does not leave the opportunity with no allocations.
 */
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * @param opportunityId  Opportunity whose GAU allocations are replaced.
     * @param percentByGauId Map of npsp__General_Accounting_Unit__c Id to percentage (60 = 60%).
     * @return The inserted npsp__Allocation__c records.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ---------- Validation (no DML before this point) ----------

        if (opportunityId == null) {
            throw new AllocationException('An opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage is required.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A GAU Id in the allocation map is null.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' is null.');
            }
            if (pct <= 0) {
                throw new AllocationException(
                    'Percentage for GAU ' + gauId + ' must be greater than 0.'
                );
            }
            total += pct;
        }

        if (total > 100) {
            throw new AllocationException(
                'Allocation percentages total ' + total + '%, which exceeds 100%.'
            );
        }

        // Confirm the opportunity exists and the user can read it.
        List<Opportunity> opps = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
        ];
        if (opps.isEmpty()) {
            throw new AllocationException('Opportunity ' + opportunityId + ' was not found.');
        }

        // Confirm every GAU exists and is active.
        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
                WITH USER_MODE
            ]
        );

        List<String> missingGaus = new List<String>();
        List<String> inactiveGaus = new List<String>();
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null) {
                missingGaus.add(String.valueOf(gauId));
            } else if (gau.npsp__Active__c != true) {
                inactiveGaus.add(gau.Name + ' (' + gauId + ')');
            }
        }
        if (!missingGaus.isEmpty()) {
            throw new AllocationException(
                'GAU(s) not found or not accessible: ' + String.join(missingGaus, ', ')
            );
        }
        if (!inactiveGaus.isEmpty()) {
            throw new AllocationException(
                'Inactive GAU(s) cannot be allocated: ' + String.join(inactiveGaus, ', ')
            );
        }

        // Build new allocations. Percent only: NPSP derives the amount from the opportunity.
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        // ---------- DML (single savepoint, rollback on failure) ----------

        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
            WITH USER_MODE
        ];

        Savepoint sp = Database.setSavepoint();
        try {
            if (!existing.isEmpty()) {
                delete as user existing;
            }
            insert as user newAllocations;
        } catch (DmlException e) {
            Database.rollback(sp);
            throw new AllocationException(
                'Failed to save GAU allocations: ' + e.getMessage()
            );
        }

        return newAllocations;
    }
}
