/**
 * Creates a single NPSP Household Account for a new family and attaches all
 * supplied (new) contacts to it. The first contact is the household's primary
 * contact.
 *
 * Design notes:
 *  - The household is created by NPSP itself when the first contact is inserted
 *    without an AccountId. NPSP then names the household and generates greetings.
 *    This avoids setting Account.Name manually and avoids hard-coding record type Ids.
 *  - Only the first contact is inserted without an AccountId. Inserting the whole
 *    list at once without AccountIds would let NPSP create one household per contact
 *    (or several for differing last names), leaving extra accounts behind.
 *  - The remaining contacts are inserted with the household's AccountId set, so
 *    NPSP attaches them to the existing household instead of creating new ones.
 *  - The whole operation runs under a savepoint, so a failure leaves no partial
 *    household or contacts behind.
 */
public with sharing class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must be a non-null, non-empty list of Contacts.');
        }

        Contact primary = members[0];
        Savepoint sp = Database.setSavepoint();

        try {
            // 1. Insert the primary contact with no AccountId so NPSP creates the household.
            primary.AccountId = null;
            insert primary;

            Id householdId = [
                SELECT AccountId
                FROM Contact
                WHERE Id = :primary.Id
                LIMIT 1
            ].AccountId;

            if (householdId == null) {
                throw new IllegalStateException('NPSP did not create a household account for the primary contact.');
            }

            // 2. Attach the remaining members to the same household and insert them in bulk.
            List<Contact> others = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact c = members[i];
                c.AccountId = householdId;
                others.add(c);
            }
            if (!others.isEmpty()) {
                insert others;
            }

            // 3. Ensure the household is a Household Account (looked up by DeveloperName,
            //    not hard-coded) and that its primary contact is the first member.
            List<RecordType> hhRecordTypes = [
                SELECT Id
                FROM RecordType
                WHERE SObjectType = 'Account'
                  AND DeveloperName = 'HH_Account'
                  AND IsActive = true
                LIMIT 1
            ];
            if (hhRecordTypes.isEmpty()) {
                throw new IllegalStateException('Active Account record type HH_Account was not found.');
            }

            Account household = [
                SELECT Id, RecordTypeId
                FROM Account
                WHERE Id = :householdId
                LIMIT 1
            ];

            Account toUpdate = new Account(
                Id = householdId,
                npe01__One2OneContact__c = primary.Id
            );
            if (household.RecordTypeId != hhRecordTypes[0].Id) {
                toUpdate.RecordTypeId = hhRecordTypes[0].Id;
            }
            update toUpdate;

            return householdId;

        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }
}
