public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Ensures each contact has exactly one OpportunityContactRole on the opportunity
     * with the requested role, and a single NPSP partial soft credit linked to it.
     *
     * Bulk profile: 2 SOQL queries and at most 3 DML statements regardless of request count.
     * All validation runs before any DML, so a failed validation changes nothing.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---- Phase 1: structural validation (no queries) ----
        Map<String, SoftCreditRequest> requestByKey = new Map<String, SoftCreditRequest>();
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            if (req == null) {
                throw new SoftCreditException('Soft credit request cannot be null.');
            }
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Each soft credit request needs an opportunityId and a contactId.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be positive for opportunity ' + req.opportunityId + '.');
            }
            if (String.isBlank(req.role)) {
                throw new SoftCreditException('Soft credit role is required for opportunity ' + req.opportunityId + '.');
            }

            String k = keyOf(req.opportunityId, req.contactId);
            if (requestByKey.containsKey(k)) {
                throw new SoftCreditException('Duplicate opportunity/contact pair in one call: ' + k + '.');
            }
            requestByKey.put(k, req);
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ---- Query 1: opportunities, primary contact, and their contact roles ----
        Map<Id, Opportunity> oppById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c,
                (SELECT Id, ContactId, Role FROM OpportunityContactRoles)
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        // ---- Phase 2: business validation (still before any DML) ----
        for (SoftCreditRequest req : requestByKey.values()) {
            Opportunity opp = oppById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId + '.');
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Contact ' + req.contactId + ' is the primary contact of opportunity ' + req.opportunityId + ' and cannot receive a partial soft credit.');
            }
            Decimal oppAmount = (opp.Amount == null) ? 0 : opp.Amount;
            if (req.amount > oppAmount) {
                throw new SoftCreditException('Soft credit amount ' + req.amount + ' exceeds the amount of opportunity ' + req.opportunityId + '.');
            }
        }

        // ---- Query 2: existing partial soft credits for these opp/contact combinations ----
        Map<String, List<npsp__Partial_Soft_Credit__c>> existingByKey = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c IN :contactIds
            ORDER BY Id
        ]) {
            String k = keyOf(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!requestByKey.containsKey(k)) {
                continue;
            }
            if (!existingByKey.containsKey(k)) {
                existingByKey.put(k, new List<npsp__Partial_Soft_Credit__c>());
            }
            existingByKey.get(k).add(psc);
        }

        // ---- Phase 3: build the plan in memory (no DML) ----
        List<OpportunityContactRole> ocrToUpsert = new List<OpportunityContactRole>();
        List<SObject> toDelete = new List<SObject>();
        Map<String, OpportunityContactRole> keeperByKey = new Map<String, OpportunityContactRole>();

        for (String k : requestByKey.keySet()) {
            SoftCreditRequest req = requestByKey.get(k);
            Opportunity opp = oppById.get(req.opportunityId);

            List<OpportunityContactRole> roles = new List<OpportunityContactRole>();
            if (opp.OpportunityContactRoles != null) {
                for (OpportunityContactRole ocr : opp.OpportunityContactRoles) {
                    if (ocr.ContactId == req.contactId) {
                        roles.add(ocr);
                    }
                }
            }

            // Prefer an existing role already carrying the requested name, otherwise reuse the first one.
            OpportunityContactRole keeper = null;
            for (OpportunityContactRole ocr : roles) {
                if (ocr.Role == req.role) {
                    keeper = ocr;
                    break;
                }
            }
            if (keeper == null && !roles.isEmpty()) {
                keeper = roles[0];
            }

            if (keeper == null) {
                keeper = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrToUpsert.add(keeper);
            } else {
                if (keeper.Role != req.role) {
                    keeper.Role = req.role;
                    ocrToUpsert.add(keeper);
                }
                // Enforce exactly one contact role for this contact on this opportunity.
                for (OpportunityContactRole ocr : roles) {
                    if (ocr.Id != keeper.Id) {
                        toDelete.add(ocr);
                    }
                }
            }
            keeperByKey.put(k, keeper);
        }

        // ---- DML 1: contact roles (new and updated) so every keeper has an Id ----
        if (!ocrToUpsert.isEmpty()) {
            upsert ocrToUpsert;
        }

        // ---- Phase 4: build partial soft credits now that contact role Ids are known ----
        List<npsp__Partial_Soft_Credit__c> pscToUpsert = new List<npsp__Partial_Soft_Credit__c>();

        for (String k : requestByKey.keySet()) {
            SoftCreditRequest req = requestByKey.get(k);
            OpportunityContactRole keeper = keeperByKey.get(k);
            List<npsp__Partial_Soft_Credit__c> existing = existingByKey.get(k);

            npsp__Partial_Soft_Credit__c psc;
            if (existing == null || existing.isEmpty()) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId
                );
            } else {
                psc = existing[0];
                for (Integer i = 1; i < existing.size(); i++) {
                    toDelete.add(existing[i]);
                }
            }

            psc.npsp__Amount__c = req.amount;
            psc.npsp__Role_Name__c = req.role;
            psc.npsp__Contact_Role_ID__c = String.valueOf(keeper.Id);
            pscToUpsert.add(psc);
        }

        // ---- DML 2: partial soft credits ----
        if (!pscToUpsert.isEmpty()) {
            upsert pscToUpsert;
        }

        // ---- DML 3: remove surplus contact roles and duplicate soft credits ----
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
    }

    private static String keyOf(Id oppId, Id contactId) {
        return String.valueOf(oppId) + ':' + String.valueOf(contactId);
    }
}
