/**
 * Records an already-received gift as a Closed Won NPSP donation.
 *
 * Household model: the opportunity is placed on the contact's household account,
 * the contact is the primary contact (npsp__Primary_Contact__c) and holds the
 * Donor role, and all other household members hold the Household Member role.
 * Each contact ends up with exactly one contact role on the gift, and the gift
 * ends up with exactly one payment, marked paid for the full amount on giftDate.
 *
 * Re-running reconciliation is idempotent with respect to roles and payments:
 * existing roles are reused or corrected, and duplicates are removed.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';
    private static final Integer MAX_OPPORTUNITY_NAME_LENGTH = 120;
    private static final String DONATION_SUFFIX_WORD = ' Donation ';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('contactId is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('amount must be a non-null value greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('giftDate is required.');
        }

        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            WITH USER_MODE
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact not found: ' + contactId);
        }
        Contact donor = donors[0];
        Id householdId = donor.AccountId;
        if (householdId == null) {
            throw new IllegalArgumentException('Contact ' + donor.Id + ' has no household account.');
        }

        // 1. Create the Closed Won opportunity on the household account.
        Opportunity opp = new Opportunity(
            Name = buildOpportunityName(donor, giftDate),
            AccountId = householdId,
            Amount = amount,
            CloseDate = giftDate,
            StageName = STAGE_CLOSED_WON,
            npsp__Primary_Contact__c = donor.Id
        );
        insert opp;

        // 2. Reconcile contact roles: one role per contact, Donor for the donor,
        //    Household Member for everyone else in the household.
        reconcileContactRoles(opp.Id, donor.Id, householdId);

        // 3. Reconcile payments: exactly one paid payment for the full amount.
        reconcilePayment(opp.Id, amount, giftDate);

        return opp.Id;
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static String buildOpportunityName(Contact donor, Date giftDate) {
        String personName = String.isBlank(donor.FirstName)
            ? donor.LastName
            : donor.FirstName + ' ' + donor.LastName;
        String suffix = DONATION_SUFFIX_WORD + formatIsoDate(giftDate);

        Integer maxPersonLength = MAX_OPPORTUNITY_NAME_LENGTH - suffix.length();
        if (personName.length() > maxPersonLength) {
            personName = personName.substring(0, maxPersonLength);
        }
        return personName + suffix;
    }

    private static String formatIsoDate(Date d) {
        return String.valueOf(d.year()) + '-' + padTwo(d.month()) + '-' + padTwo(d.day());
    }

    private static String padTwo(Integer n) {
        return (n < 10 ? '0' : '') + String.valueOf(n);
    }

    private static void reconcileContactRoles(Id opportunityId, Id donorId, Id householdId) {
        // Desired state: contactId -> role
        Map<Id, String> desiredRoles = new Map<Id, String>();
        List<Contact> householdContacts = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :householdId
            WITH USER_MODE
        ];
        for (Contact member : householdContacts) {
            desiredRoles.put(member.Id, ROLE_HOUSEHOLD_MEMBER);
        }
        desiredRoles.put(donorId, ROLE_DONOR);

        // Existing state (NPSP may have auto-created roles when the primary contact was set).
        List<OpportunityContactRole> existing = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            WITH USER_MODE
            ORDER BY CreatedDate ASC
        ];

        Map<Id, OpportunityContactRole> keep = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();

        for (OpportunityContactRole ocr : existing) {
            // Delete duplicates and roles for contacts that should not be on this gift.
            if (!desiredRoles.containsKey(ocr.ContactId) || keep.containsKey(ocr.ContactId)) {
                toDelete.add(ocr);
            } else {
                keep.put(ocr.ContactId, ocr);
            }
        }

        List<OpportunityContactRole> demoteFirst = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();

        for (Id cid : desiredRoles.keySet()) {
            String role = desiredRoles.get(cid);
            Boolean isPrimary = (cid == donorId);

            if (keep.containsKey(cid)) {
                OpportunityContactRole ocr = keep.get(cid);
                if (ocr.Role != role || ocr.IsPrimary != isPrimary) {
                    ocr.Role = role;
                    ocr.IsPrimary = isPrimary;
                    if (isPrimary) {
                        toUpdate.add(ocr);
                    } else {
                        demoteFirst.add(ocr);
                    }
                }
            } else {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = cid,
                    Role = role,
                    IsPrimary = isPrimary
                ));
            }
        }

        // Order matters: only one contact role per opportunity may be primary,
        // so clear any existing primary flag before setting the new one.
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!demoteFirst.isEmpty()) {
            update demoteFirst;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    private static void reconcilePayment(Id opportunityId, Decimal amount, Date giftDate) {
        // NPSP Payments may auto-create a scheduled payment on opportunity insert.
        List<npe01__OppPayment__c> payments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
            ORDER BY CreatedDate ASC
        ];

        npe01__OppPayment__c payment;
        List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();

        if (payments.isEmpty()) {
            payment = new npe01__OppPayment__c(npe01__Opportunity__c = opportunityId);
        } else {
            payment = payments[0];
            for (Integer i = 1; i < payments.size(); i++) {
                extras.add(payments[i]);
            }
        }

        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
        payment.npe01__Paid__c = true;

        if (!extras.isEmpty()) {
            delete extras;
        }
        if (payment.Id == null) {
            insert payment;
        } else {
            update payment;
        }
    }
}
