/**
 * Links parent contacts to child contacts as NPSP "Parent" relationships.
 *
 * Only the child -> parent record (Type = 'Parent') is inserted. NPSP's
 * relationship trigger creates the reciprocal parent -> child record using the
 * List Setting lookup (Male: Son, Female: Daughter, Neutral: Child), so inserting
 * both directions here would create duplicates.
 *
 * Bulk-safe: one SOQL query to find existing links in either direction, and one
 * DML statement to insert the new relationships.
 */
public with sharing class FamilyService {

    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect valid, distinct pairs. Skip null values and self-links.
        Map<Id, Id> validPairs = new Map<Id, Id>();
        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            validPairs.put(childId, parentId);
            childIds.add(childId);
            parentIds.add(parentId);
        }
        if (validPairs.isEmpty()) {
            return;
        }

        // Single query: any relationship between a child and a parent, in either direction.
        // Keys are stored in both orders so that a lookup by (child, parent) finds
        // a record regardless of which contact is stored as Contact__c.
        Set<String> existingKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
               OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ]) {
            existingKeys.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
            existingKeys.add(pairKey(rel.npe4__RelatedContact__c, rel.npe4__Contact__c));
        }

        // Build the child -> parent relationships for pairs not already linked.
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : validPairs.keySet()) {
            Id parentId = validPairs.get(childId);
            String key = pairKey(childId, parentId);
            if (existingKeys.contains(key)) {
                continue;
            }

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = TYPE_PARENT,
                npe4__Status__c = STATUS_CURRENT
            ));

            // Mark both directions as handled so the same pair cannot be inserted twice.
            existingKeys.add(key);
            existingKeys.add(pairKey(parentId, childId));
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    private static String pairKey(Id contactId, Id relatedContactId) {
        return String.valueOf(contactId) + '|' + String.valueOf(relatedContactId);
    }
}
