public with sharing class RecordAccessService {

    // UserRecordAccess is filtered by RecordId, so chunk the input to keep each
    // query's IN list modest. 2,000 IDs / 200 per chunk = 10 SOQL queries,
    // within the 20-query budget.
    @TestVisible
    private static final Integer CHUNK_SIZE = 200;

    /**
     * Returns the subset of recordIds the running user can edit, as reported by
     * UserRecordAccess.HasEditAccess. This covers object permissions, ownership,
     * sharing rules, role hierarchy, and View All / Modify All.
     *
     * Null or empty input returns an empty set (never null). IDs with no
     * UserRecordAccess row (not visible to the user, or nonexistent) are excluded.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // Drop nulls and collapse duplicates before querying.
        Set<Id> uniqueIds = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                uniqueIds.add(recordId);
            }
        }
        if (uniqueIds.isEmpty()) {
            return result;
        }

        List<Id> ids = new List<Id>(uniqueIds);
        Id currentUserId = UserInfo.getUserId();

        for (Integer start = 0; start < ids.size(); start += CHUNK_SIZE) {
            Integer finish = Math.min(start + CHUNK_SIZE, ids.size());
            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < finish; i++) {
                chunk.add(ids[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess == true) {
                    result.add(access.RecordId);
                }
            }
        }

        return result;
    }
}
