/**
 * Imports legacy Contact records without firing the welcome-task action.
 *
 * Only TA_Contact_CreateWelcomeTask is bypassed. Every other Contact action
 * (including TA_Contact_FormatPhone) still runs. The bypass is scoped to this
 * method: it is cleared in a finally block, so later DML in the same transaction
 * gets its welcome task as usual. If the caller already had this action bypassed,
 * the bypass is left in place.
 */
public with sharing class ContactImportService {

    public static void importContacts(List<Contact> contacts) {
        Boolean wasAlreadyBypassed = MetadataTriggerHandler.isBypassed(TA_Contact_CreateWelcomeTask.class);

        if (!wasAlreadyBypassed) {
            MetadataTriggerHandler.bypass(TA_Contact_CreateWelcomeTask.class);
        }

        try {
            insert contacts;
        } finally {
            if (!wasAlreadyBypassed) {
                MetadataTriggerHandler.clearBypass(TA_Contact_CreateWelcomeTask.class);
            }
        }
    }
}
