```apex
/**
 * Moves ownership of a set of Accounts and all of their Contacts to a new owner.
 *
 * Account trigger actions (Trigger Actions Framework) are bypassed for the whole
 * ownership change, including the Contact update, so that territory recalculation
 * does not run. Contact trigger actions run normally.
 *
 * Governor usage: 1 SOQL query (Contacts) and at most 2 DML statements (Accounts, Contacts),
 * regardless of volume.
 */
public with sharing class AccountOwnershipService {

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Single query for all child Contacts of the target Accounts.
        List<Contact> contacts = [
            SELECT Id, OwnerId
            FROM Contact
            WHERE AccountId IN :accountIds
            WITH USER_MODE
        ];

        // Build the Account updates without querying: only Id and OwnerId are needed.
        List<Account> accounts = new List<Account>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                accounts.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }
        }

        for (Contact c : contacts) {
            c.OwnerId = newOwnerId;
        }

        // Only clear the Account bypass at the end if this method set it, so that a
        // bypass already in place for the caller's transaction is left untouched.
        Boolean setAccountBypass = !TriggerBase.isBypassed(Schema.Account.SObjectType);
        if (setAccountBypass) {
            TriggerBase.bypass(Schema.Account.SObjectType);
        }

        try {
            // All-or-none: a plain DML statement rolls back on failure and throws,
            // and the exception propagates unchanged to the caller.
            if (!accounts.isEmpty()) {
                update accounts;
            }
            if (!contacts.isEmpty()) {
                update contacts;
            }
        } finally {
            if (setAccountBypass) {
                TriggerBase.clearBypass(Schema.Account.SObjectType);
            }
        }
    }
}
