@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    private static Id oppId(Integer seed) {
        // Fake Ids from TAF's test utility; no records are inserted.
        return TriggerTestUtility.getFakeId(Opportunity.SObjectType);
    }

    private static Opportunity opp(Id recordId, Decimal amount) {
        return new Opportunity(Id = recordId, Amount = amount);
    }

    private static void runBeforeUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);
    }

    @IsTest
    static void reductionOfMoreThanHalfIsRejected() {
        Id recordId = oppId(1);
        Opportunity oldOpp = opp(recordId, 1000);
        Opportunity newOpp = opp(recordId, 499);

        runBeforeUpdate(new List<Opportunity>{ newOpp }, new List<Opportunity>{ oldOpp });

        Assert.isTrue(newOpp.hasErrors(), 'Reducing Amount by more than half must add an error.');
        List<Database.Error> errors = newOpp.getErrors();
        Assert.areEqual(1, errors.size(), 'Exactly one error expected.');
        Assert.areEqual(TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE, errors[0].getMessage(),
            'Error message must match ERROR_MESSAGE.');
    }

    @IsTest
    static void reductionOfExactlyHalfIsAccepted() {
        Id recordId = oppId(2);
        Opportunity oldOpp = opp(recordId, 1000);
        Opportunity newOpp = opp(recordId, 500);

        runBeforeUpdate(new List<Opportunity>{ newOpp }, new List<Opportunity>{ oldOpp });

        Assert.isFalse(newOpp.hasErrors(), 'A reduction to exactly half must not add an error.');
        Assert.areEqual(0, newOpp.getErrors().size(), 'No errors expected.');
    }

    @IsTest
    static void increaseIsAccepted() {
        Id recordId = oppId(3);
        Opportunity oldOpp = opp(recordId, 1000);
        Opportunity newOpp = opp(recordId, 1500);

        runBeforeUpdate(new List<Opportunity>{ newOpp }, new List<Opportunity>{ oldOpp });

        Assert.isFalse(newOpp.hasErrors(), 'An increase must not add an error.');
        Assert.areEqual(0, newOpp.getErrors().size(), 'No errors expected.');
    }

    @IsTest
    static void previousAmountNullIsAcceptedWithoutException() {
        Id recordId = oppId(4);
        Opportunity oldOpp = opp(recordId, null);
        Opportunity newOpp = opp(recordId, 100);

        Boolean threw = false;
        try {
            runBeforeUpdate(new List<Opportunity>{ newOpp }, new List<Opportunity>{ oldOpp });
        } catch (Exception e) {
            threw = true;
        }

        Assert.isFalse(threw, 'A null previous Amount must not cause an exception.');
        Assert.isFalse(newOpp.hasErrors(), 'A null previous Amount must not add an error.');
    }

    @IsTest
    static void onlyViolatingRecordsInBulkGetErrors() {
        Id rejectedA = oppId(5);
        Id acceptedB = oppId(6);
        Id rejectedC = oppId(7);
        Id acceptedD = oppId(8);

        Opportunity oldA = opp(rejectedA, 1000);
        Opportunity oldB = opp(acceptedB, 1000);
        Opportunity oldC = opp(rejectedC, 2000);
        Opportunity oldD = opp(acceptedD, 300);

        Opportunity newA = opp(rejectedA, 400);   // more than half reduction
        Opportunity newB = opp(acceptedB, 800);   // reduction below half: accepted
        Opportunity newC = opp(rejectedC, 999);   // more than half reduction
        Opportunity newD = opp(acceptedD, 300);   // unchanged: accepted

