/**
 * Trigger action for Contact (registered through Trigger_Action__mdt records).
 *
 * Rule: two Contacts on the same Account may not share an email address
 * (compared case-insensitively). Contacts without an AccountId or Email are not checked.
 *
 * - Insert: every contact with an Account and Email is checked.
 * - Update: only contacts whose Email or AccountId changed are checked. A contact never
 *   conflicts with itself.
 * - Within one save the first record in the list is accepted and later duplicates are rejected.
 * - Conflicts are reported per record with addError, so valid records in the same save still succeed.
 * - One SOQL query per execution, regardless of batch size (up to 200 records).
 *
 * Runs without sharing so that the uniqueness check sees every Contact in the org, regardless of the
 * running user's sharing access.
 */
public without sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    @TestVisible
    private static final String DUPLICATE_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        check((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        check((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private static void check(List<Contact> newContacts, List<Contact> oldContacts) {
        if (newContacts == null || newContacts.isEmpty()) {
            return;
        }

        Boolean isUpdate = oldContacts != null;

        // Collect the keys needed for the single query.
        Set<Id> batchIds = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact c : newContacts) {
            if (c.Id != null) {
                batchIds.add(c.Id);
            }
            if (isCandidate(c)) {
                accountIds.add(c.AccountId);
                emails.add(c.Email.toLowerCase());
            }
        }

        // Keys already held by contacts that are not part of this save.
        // Contacts in this save are excluded because their stored values are stale;
        // they are evaluated against their new values in memory below.
        Set<String> occupied = new Set<String>();
        if (!accountIds.isEmpty()) {
            for (Contact existing : [
                SELECT AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email IN :emails
                  AND Id NOT IN :batchIds
            ]) {
                occupied.add(buildKey(existing.AccountId, existing.Email));
            }
        }

        // Pass 1: contacts in this save that are not being checked (unchanged on update)
        // still hold their email, so later changed contacts must not take it.
        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact c = newContacts[i];
            if (!isCandidate(c)) {
                continue;
            }
            if (isUpdate && !isChanged(c, oldContacts[i])) {
                occupied.add(buildKey(c.AccountId, c.Email));
            }
        }

        // Pass 2: check inserted and changed contacts in list order.
        // The first holder of a key is accepted; each later one is rejected.
        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact c = newContacts[i];
            if (!isCandidate(c)) {
                continue;
            }
            if (isUpdate && !isChanged(c, oldContacts[i])) {
                continue;
            }

            String key = buildKey(c.AccountId, c.Email);
            if (occupied.contains(key)) {
                c.addError(DUPLICATE_MESSAGE);
            } else {
                occupied.add(key);
            }
        }
    }

    private static Boolean isCandidate(Contact c) {
        return c.AccountId != null && String.isNotBlank(c.Email);
    }

    private static Boolean isChanged(Contact newContact, Contact oldContact) {
        return newContact.Email != oldContact.Email
            || newContact.AccountId != oldContact.AccountId;
    }

    private static String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }
}
