/**
 * Trigger Action (TAF 0.3.4) that normalizes Lead contact data on insert.
 * Runs in the before insert context, so changes are saved with the record:
 * no extra DML and no SOQL. Bulk-safe: it only loops over triggerNew.
 */
public class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject so : triggerNew) {
            Lead newLead = (Lead) so;

            // Email: trim and lower-case; a null email stays null.
            if (newLead.Email != null) {
                newLead.Email = newLead.Email.trim().toLowerCase();
            }

            // Company: trim surrounding whitespace only.
            if (newLead.Company != null) {
                newLead.Company = newLead.Company.trim();
            }

            // LeadSource: default to 'Web' when blank; keep any existing value.
            if (String.isBlank(newLead.LeadSource)) {
                newLead.LeadSource = 'Web';
            }
        }
    }
}
