/**
 * Keeps Account.FB_Open_Case_Count__c equal to the number of the account's open Cases
 * (IsClosed = false). Registered for after insert, after update, after delete and after
 * undelete through Trigger_Action__mdt records.
 *
 * Bulk-safe: per trigger execution it issues exactly 2 SOQL queries and at most 1 DML
 * statement, regardless of how many Cases are in the batch.
 *
 * Approach: collect every affected Account Id from the trigger records, then recount the
 * open Cases for those accounts with one aggregate query and write back only the accounts
 * whose stored value differs. Accounts with no open Cases are counted as 0.
 *
 * without sharing: the count must reflect all Cases on the account, not only those visible
 * to the user performing the DML. The class only ever writes the count field.
 */
public without sharing class TA_Case_RollupOpenCount implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            Case c = (Case) record;
            if (!c.IsClosed) {
                addAccountId(accountIds, c.AccountId);
            }
        }
        recount(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        // Match old and new by Id rather than by list position, so that entry-criteria
        // filtering by the framework cannot misalign the two lists.
        Map<Id, SObject> oldById = new Map<Id, SObject>(triggerOld);
        Set<Id> accountIds = new Set<Id>();

        for (SObject record : triggerNew) {
            Case newCase = (Case) record;
            Case oldCase = (Case) oldById.get(newCase.Id);
            if (oldCase == null) {
                continue;
            }
            // Nothing that affects the count changed.
            if (newCase.AccountId == oldCase.AccountId && newCase.IsClosed == oldCase.IsClosed) {
                continue;
            }
            // The case was counted against its old account if it was open there.
            if (!oldCase.IsClosed) {
                addAccountId(accountIds, oldCase.AccountId);
            }
            // The case is counted against its new account if it is open there.
            if (!newCase.IsClosed) {
                addAccountId(accountIds, newCase.AccountId);
            }
        }
        recount(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerOld) {
            Case c = (Case) record;
            if (!c.IsClosed) {
                addAccountId(accountIds, c.AccountId);
            }
        }
        recount(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            Case c = (Case) record;
            if (!c.IsClosed) {
                addAccountId(accountIds, c.AccountId);
            }
        }
        recount(accountIds);
    }

    private static void addAccountId(Set<Id> accountIds, Id accountId) {
        if (accountId != null) {
            accountIds.add(accountId);
        }
    }

    /**
     * Recounts open Cases for the given accounts and updates the stored count where it differs.
     * Query 1: aggregate count of open Cases per account (SOQL #1).
     * Query 2: the affected accounts and their current stored count (SOQL #2). Accounts that no
     *          longer exist (e.g. removed in the same transaction) are simply not returned, so
     *          they are never updated.
     * DML: one update of the changed accounts, if any.
     */
    private static void recount(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();
        for (AggregateResult ar : [
                SELECT AccountId acctId, COUNT(Id) openCases
                FROM Case
                WHERE AccountId IN :accountIds
                  AND IsClosed = false
                GROUP BY AccountId
        ]) {
            openCountByAccount.put((Id) ar.get('acctId'), (Integer) ar.get('openCases'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
                SELECT Id, FB_Open_Case_Count__c
                FROM Account
                WHERE Id IN :accountIds
        ]) {
            Decimal target = openCountByAccount.containsKey(acc.Id)
                ? openCountByAccount.get(acc.Id)
                : 0;
            if (acc.FB_Open_Case_Count__c != target) {
                accountsToUpdate.add(new Account(Id = acc.Id, FB_Open_Case_Count__c = target));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
