public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    /*
     * Opportunity Ids already audited in this transaction. Must be static: TAF creates a new
     * action instance per trigger execution, and TA_Opportunity_RoundAmount re-updates the same
     * opportunities, which re-fires this trigger. The set ensures at most one 'Amount changed'
     * task per opportunity per transaction, so the rounding update does not create a second one.
     */
    @TestVisible
    private static Set<Id> auditedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        for (SObject record : triggerOld) {
            oldById.put(record.Id, (Opportunity) record);
        }

        List<Task> auditTasks = new List<Task>();
        for (SObject record : triggerNew) {
            Opportunity newOpp = (Opportunity) record;
            Opportunity oldOpp = oldById.get(newOpp.Id);
            if (oldOpp == null || newOpp.Amount == oldOpp.Amount) {
                continue;
            }
            // Skip if already audited in this transaction (e.g. the re-entrant pass caused by rounding).
            if (!auditedOpportunityIds.add(newOpp.Id)) {
                continue;
            }
            auditTasks.add(new Task(
                Subject = 'Amount changed',
                WhatId = newOpp.Id,
                Status = 'Completed'
            ));
        }

        if (!auditTasks.isEmpty()) {
            insert auditTasks;
        }
    }
}
